Web Application.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Web Application", "Web Application") {
    Component("Patron Portal Module", "Patron Portal Module", "React / TypeScript", "Component managing catalog browsing, reservations, and profiles.")
    Component("Staff Dashboard Module", "Staff Dashboard Module", "React / TypeScript", "Component managing circulation, cataloging, and admin workflows.")
    Component("API Client Layer", "API Client Layer", "Axios / TypeScript", "Component handling Axios HTTP communication, JWTs, and input sanitization.")
    Component("State Management Core", "State Management Core", "Zustand", "Component managing localized UI state and session context.")
}

Rel("Patron Portal Module", "API Client Layer", "Dispatches requests", "In-Memory Function Calls")
Rel("Staff Dashboard Module", "API Client Layer", "Dispatches requests", "In-Memory Function Calls")
@enduml

API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(routing_load_balancer, "Routing & Load Balancer", "Spring Cloud Gateway", "Routes incoming API requests and balances load across backend services.")
    Component(auth_filter, "Authentication & Authorization Filter", "Spring Security", "Validates OAuth2 tokens and enforces role-based access control.")
    Component(rate_limiting, "Rate Limiting & Throttling", "Spring Cloud Gateway & Redis", "Controls request rates and enforces traffic limits.")
    Component(caching_transformation, "Caching & Response Transformation", "Spring Cloud Gateway & Redis", "Evaluates cached responses and transforms payloads for efficient delivery.")
}

Rel(routing_load_balancer, caching_transformation, "Evaluates cached responses", "Redis RESP / TLS")

@enduml

Database.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Database container

Container_Boundary(database, "Database") {
    Component(ConnectionPooler, "Connection Pooler", "PgBouncer", "Enterprise connection pooler to prevent backend worker exhaustion.")
    Component(RelationalTables, "Relational Tables", "PostgreSQL SQL / PostgreSQL RLS / pgcrypto", "ACID-compliant relational persistence with row-level security and column-level encryption for patron isolation.")
    Component(AuditLoggingModule, "Audit Logging Module", "pgAudit extension", "Database event tracking for EU regulatory compliance.")
}

Rel(ConnectionPooler, RelationalTables, "Forwards pooled connections", "PostgreSQL Native Protocol over TLS 1.3")
Rel(RelationalTables, AuditLoggingModule, "Captures security events", "Internal PostgreSQL Hook")

@enduml
